import { useState, useEffect, useRef } from 'react';
import { Search, X, Command, FileText, Settings, Users, Store, ArrowRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

export default function GlobalSearchModal({ isOpen, onClose }) {
  const [query, setQuery] = useState('');
  const inputRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    if (isOpen) {
      setTimeout(() => {
        inputRef.current?.focus();
      }, 100);
    } else {
      setQuery('');
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const mockResults = [
    { type: 'Setting', title: 'Auto Assignment', path: '/settings', icon: Settings },
    { type: 'Setting', title: 'Home Delivery', path: '/settings', icon: Settings },
    { type: 'Customer', title: 'John Doe', path: '/customers', icon: Users },
    { type: 'Order', title: '#ORD-10492', path: '/orders', icon: FileText },
    { type: 'Store', title: 'Koramangala Branch', path: '/stores', icon: Store },
  ];

  const filteredResults = query 
    ? mockResults.filter(r => r.title.toLowerCase().includes(query.toLowerCase()) || r.type.toLowerCase().includes(query.toLowerCase()))
    : [];

  return (
    <div className="fixed inset-0 z-[100] flex items-start justify-center pt-[15vh] sm:pt-[20vh] px-4 bg-background/80 backdrop-blur-sm animate-in fade-in duration-200">
      {/* Backdrop click to close */}
      <div className="absolute inset-0" onClick={onClose} />

      <div className="relative bg-card w-full max-w-2xl rounded-2xl shadow-2xl border border-border overflow-hidden animate-in slide-in-from-top-4 duration-300">

        {/* Search Header */}
        <div className="flex items-center px-4 border-b border-border bg-card relative">
          <Search className="w-5 h-5 text-muted-foreground shrink-0" />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search settings, orders, customers..."
            className="flex-1 bg-transparent border-none outline-none px-4 py-5 text-base font-medium text-foreground placeholder:text-muted-foreground"
          />
          <button 
            onClick={onClose}
            className="p-1.5 rounded-md hover:bg-muted text-muted-foreground transition-colors shrink-0"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Results Body */}
        <div className="max-h-[60vh] overflow-y-auto p-2">
          {!query && (
            <div className="p-8 text-center text-muted-foreground">
              <Command className="w-8 h-8 mx-auto mb-3 opacity-20" />
              <p className="text-sm font-medium">Type to start searching</p>
              <p className="text-xs mt-1 opacity-60">Find settings, recent orders, or customer profiles</p>
            </div>
          )}

          {query && filteredResults.length === 0 && (
            <div className="p-8 text-center text-muted-foreground">
              <Search className="w-8 h-8 mx-auto mb-3 opacity-20" />
              <p className="text-sm font-medium">No results found for "{query}"</p>
            </div>
          )}

          {query && filteredResults.length > 0 && (
            <div className="space-y-1">
              <div className="px-3 py-2 text-xs font-black uppercase tracking-wider text-muted-foreground opacity-60">
                Search Results
              </div>
              {filteredResults.map((result, idx) => (
                <button
                  key={idx}
                  onClick={() => {
                    navigate(result.path);
                    onClose();
                  }}
                  className="w-full flex items-center justify-between p-3 rounded-xl hover:bg-muted transition-colors group text-left"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-lg bg-background border border-border flex items-center justify-center shrink-0">
                      <result.icon className="w-5 h-5 text-muted-foreground group-hover:text-primary transition-colors" />
                    </div>
                    <div>
                      <h4 className="text-sm font-bold text-foreground group-hover:text-primary transition-colors">
                        {result.title}
                      </h4>
                      <p className="text-[11px] font-medium text-muted-foreground mt-0.5">
                        {result.type} ΓÇó {result.path}
                      </p>
                    </div>
                  </div>
                  <ArrowRight className="w-4 h-4 text-muted-foreground opacity-0 group-hover:opacity-100 -translate-x-2 group-hover:translate-x-0 transition-all" />
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { NavLink, useLocation, useNavigate } from 'react-router-dom';
import { 
  Home, Users, ShoppingBag, Menu, Package, Store, 
  Settings, ChevronLeft, ChevronRight, BarChart3, 
  Tag, ToggleLeft, Globe, LogOut, User as UserIcon, Building, HelpCircle, ChevronUp, LayoutDashboard, Server, Bell, X, Moon, Sun, Search
} from 'lucide-react';
import GlobalSearchModal from './GlobalSearchModal';

const NAV_GROUPS = [
  {
    title: 'Analytics',
    items: [
      { name: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
      { name: 'Reports & BI', href: '/reports', icon: BarChart3 },
    ]
  },
  {
    title: 'Operations',
    items: [
      { name: 'Orders', href: '/orders', icon: ShoppingBag },
      { name: 'Customers', href: '/customers', icon: Users },
      { name: 'Stores', href: '/stores', icon: Store },
      { name: 'Notifications', href: '/notifications', icon: Bell },
    ]
  },
  {
    title: 'Menu Engine',
    items: [
      { name: 'Menu', href: '/menu', icon: Menu },
      { name: 'Offers', href: '/offers', icon: Tag },
      { name: 'Availability', href: '/availability', icon: ToggleLeft },
      { name: 'Inventory', href: '/inventory', icon: Package },
    ]
  }
];

const SETTINGS_NAV = [
  { name: 'Store Settings', href: '/settings', icon: Settings },
  { name: 'Global Settings', href: '/global-settings', icon: Globe },
];

export default function Sidebar({ onOpenSwitchModal, activeBrand, isMobileOpen, onMobileClose }) {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    return document.documentElement.classList.contains('dark') || 
           localStorage.getItem('theme') === 'dark';
  });
  const location = useLocation();
  const navigate = useNavigate();
  const menuRef = useRef(null);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => {
    function handleClickOutside(event) {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setIsProfileMenuOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const sidebarContent = (isMobile) => (
    <>
      {/* Brand Header */}
      <div className="h-16 flex items-center justify-between px-6 border-b border-border shrink-0">
        <span className={`text-xl font-black text-foreground whitespace-nowrap overflow-hidden transition-all duration-300 ${!isMobile && isCollapsed ? 'opacity-0 w-0' : 'opacity-100 w-auto tracking-tight'}`}>
          Restrobopos
        </span>
        {!isMobile && (
          <span className={`text-2xl font-black text-primary transition-all duration-300 ${isCollapsed ? 'opacity-100 block mx-auto' : 'opacity-0 hidden'}`}>
            RB
          </span>
        )}
        {isMobile && (
          <button onClick={onMobileClose} className="p-1.5 rounded-lg hover:bg-muted text-muted-foreground">
            <X className="w-5 h-5" />
          </button>
        )}
      </div>

      {/* Collapse Toggle ΓÇö desktop only */}
      {!isMobile && (
        <button 
          onClick={() => setIsCollapsed(!isCollapsed)}
          className="absolute -right-3 top-6 bg-primary text-primary-foreground rounded-full p-1 shadow-md hover:scale-110 transition-transform z-50"
        >
          {isCollapsed ? <ChevronRight className="w-4 h-4" /> : <ChevronLeft className="w-4 h-4" />}
        </button>
      )}

      <div className="px-4 pt-4 pb-2">
        <button 
          onClick={() => { setIsSearchOpen(true); if (isMobile) onMobileClose(); }}
          className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-bold bg-muted/50 text-muted-foreground hover:bg-muted hover:text-foreground transition-all border border-border/50 hover:border-border ${!isMobile && isCollapsed ? 'justify-center' : ''}`}
        >
          <Search className="w-5 h-5 shrink-0" />
          <span className={`whitespace-nowrap transition-all duration-300 ${!isMobile && isCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100 w-auto block'}`}>
            Global Search...
          </span>
        </button>
      </div>

      {/* Navigation Groups */}
      <nav className="flex-1 px-4 py-6 space-y-8 overflow-y-auto custom-scrollbar">
        {NAV_GROUPS.map((group, idx) => (
          <div key={idx} className="space-y-2">
            {(!isMobile && !isCollapsed || isMobile) && (
              <p className="px-3 text-[10px] font-black text-muted-foreground uppercase tracking-widest mb-3 opacity-60">
                {group.title}
              </p>
            )}
            <div className="space-y-1">
              {group.items.map((item) => (
                <NavLink
                  key={item.name}
                  to={item.href}
                  onClick={() => { if (!isMobile) setIsCollapsed(true); if (isMobile) onMobileClose(); }}
                  className={({ isActive }) =>
                    `flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-bold transition-all ${
                      isActive ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:bg-muted hover:text-foreground'
                    } ${!isMobile && isCollapsed ? 'justify-center' : ''}`
                  }
                  title={!isMobile && isCollapsed ? item.name : undefined}
                >
                  <item.icon className="w-5 h-5 shrink-0" />
                  <span className={`whitespace-nowrap transition-all duration-300 ${!isMobile && isCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100 w-auto block'}`}>
                    {item.name}
                  </span>
                </NavLink>
              ))}
            </div>
          </div>
        ))}

        {/* Configuration Group */}
        <div className={`space-y-2`}>
           {(!isMobile && !isCollapsed || isMobile) && (
             <p className="px-3 text-[10px] font-black text-muted-foreground uppercase tracking-widest mb-3 opacity-60">Settings</p>
           )}
           <div className="space-y-1">
            {SETTINGS_NAV.map((item) => (
              <NavLink
                key={item.name}
                to={item.href}
                onClick={() => { if (!isMobile) setIsCollapsed(true); if (isMobile) onMobileClose(); }}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-bold transition-all ${
                    isActive ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:bg-muted hover:text-foreground'
                  } ${!isMobile && isCollapsed ? 'justify-center' : ''}`
                }
                title={!isMobile && isCollapsed ? item.name : undefined}
              >
                <item.icon className="w-5 h-5 shrink-0" />
                <span className={`whitespace-nowrap transition-all duration-300 ${!isMobile && isCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100 w-auto block'}`}>
                  {item.name}
                </span>
              </NavLink>
            ))}
           </div>
        </div>
      </nav>

      {/* Profile Section (Bottom Sticky) */}
      <div className="p-4 border-t border-border bg-muted/20 relative" ref={menuRef}>
        {/* Profile Menu Popover */}
        {isProfileMenuOpen && (
          <div className={`absolute ${!isMobile && isCollapsed ? 'left-full ml-4 bottom-0 w-64' : 'bottom-full left-4 right-4 mb-2'} bg-card border border-border rounded-xl shadow-2xl overflow-hidden animate-in fade-in ${!isMobile && isCollapsed ? 'slide-in-from-left-2' : 'slide-in-from-bottom-2'} duration-200 z-[60]`}>
            <div className="p-4 border-b border-border bg-muted/30">
              <p className="font-black text-sm text-foreground truncate">John Doe</p>
              <p className="text-[10px] font-bold text-muted-foreground truncate">john@restro.com</p>
              <div className="mt-2 inline-flex items-center px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider bg-primary/10 text-primary border border-primary/20">
                {activeBrand.role || 'Super Admin'}
              </div>
            </div>
            <div className="p-2 space-y-1">
              <button 
                onClick={() => { setIsProfileMenuOpen(false); navigate('/profile'); if (isMobileOpen) onMobileClose(); }}
                className="w-full flex items-center gap-3 px-3 py-2 text-sm font-bold rounded-lg hover:bg-muted text-foreground transition-colors text-left"
              >
                <UserIcon className="w-4 h-4 text-muted-foreground" /> My Profile
              </button>
              <button 
                onClick={() => { setIsProfileMenuOpen(false); onOpenSwitchModal(); }}
                className="w-full flex items-center gap-3 px-3 py-2 text-sm font-bold rounded-lg hover:bg-muted text-foreground transition-colors text-left"
              >
                <Building className="w-4 h-4 text-muted-foreground" /> Switch Restaurant
              </button>
              <button className="w-full flex items-center gap-3 px-3 py-2 text-sm font-bold rounded-lg hover:bg-muted text-foreground transition-colors text-left">
                <HelpCircle className="w-4 h-4 text-muted-foreground" /> Help & Support
              </button>
              <button 
                onClick={() => setIsDarkMode(!isDarkMode)}
                className="w-full flex items-center gap-3 px-3 py-2 text-sm font-bold rounded-lg hover:bg-muted text-foreground transition-colors text-left"
              >
                {isDarkMode ? <Sun className="w-4 h-4 text-muted-foreground" /> : <Moon className="w-4 h-4 text-muted-foreground" />}
                {isDarkMode ? 'Light Mode' : 'Dark Mode'}
              </button>
            </div>
            <div className="p-2 border-t border-border bg-muted/10">
              <button 
                onClick={() => {
                  localStorage.removeItem('isLoggedIn');
                  navigate('/login');
                }}
                className="w-full flex items-center gap-3 px-3 py-2 text-sm font-black rounded-lg hover:bg-red-50 text-red-600 transition-colors text-left"
              >
                <LogOut className="w-4 h-4" /> Log Out
              </button>
            </div>
          </div>
        )}

        {/* Profile Trigger */}
        <button 
          onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)}
          className={`w-full flex items-center gap-3 transition-all ${!isMobile && isCollapsed ? 'justify-center' : 'px-2 py-2 rounded-xl bg-card border border-border shadow-sm hover:border-primary/50'}`}
        >
          <div className="w-8 h-8 rounded-full bg-primary text-primary-foreground flex items-center justify-center font-black text-xs shrink-0 shadow-inner">
            JD
          </div>
          {(!isMobile && !isCollapsed || isMobile) && (
            <div className="flex-1 min-w-0 text-left">
              <p className="text-xs font-black text-foreground truncate">John Doe</p>
              <p className="text-[10px] font-medium text-muted-foreground truncate">{activeBrand.name}</p>
            </div>
          )}
          {(!isMobile && !isCollapsed || isMobile) && (
            <ChevronUp size={14} className={`text-muted-foreground transition-transform duration-300 ${isProfileMenuOpen ? 'rotate-180' : ''}`} />
          )}
        </button>
      </div>
    </>
  );

  return (
    <>
      {/* Desktop Sidebar */}
      <div className={`${isCollapsed ? 'w-20' : 'w-64'} bg-card border-r border-border flex-col hidden md:flex transition-all duration-300 relative z-50 shrink-0 shadow-lg`}>
        {sidebarContent(false)}
      </div>

      {/* Mobile Sidebar Overlay */}
      {isMobileOpen && (
        <div className="fixed inset-0 z-[90] md:hidden">
          {/* Backdrop */}
          <div 
            className="absolute inset-0 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200" 
            onClick={onMobileClose} 
          />
          {/* Drawer */}
          <div className="absolute inset-y-0 left-0 w-72 bg-card border-r border-border flex flex-col shadow-2xl animate-in slide-in-from-left duration-300 z-10">
            {sidebarContent(true)}
          </div>
        </div>
      )}

      <GlobalSearchModal isOpen={isSearchOpen} onClose={() => setIsSearchOpen(false)} />
    </>
  );
}

import { useState } from 'react';
import { Search, Calculator, AlertTriangle, TrendingDown, TrendingUp } from 'lucide-react';
import { useMenuStore } from '../../../store/useMenuStore';
import { useInventoryStore } from '../../../store/useInventoryStore';

export default function RecipeCostTab() {
  const { items, categories, variants, addonItems } = useMenuStore();
  const { ingredients } = useInventoryStore();
  const [searchQuery, setSearchQuery] = useState('');

  // We need to mock some BOMs here or pull from the RecipesTab if it was stored globally.
  // Since RecipesTab state was local in the previous implementation, let's mock a cost calculator logic
  // based on some dummy BOMs or random assignment for demonstration, as a real implementation would
  // have the BOMs in a global store (e.g. useInventoryStore or useMenuStore).

  // For demonstration, let's randomly assign 2-3 ingredients to each item to calculate cost.
  const calculateItemCost = (itemId) => {
    // Deterministic random-like based on string length to keep UI stable
    const count = (itemId.length % 3) + 2; 
    let cost = 0;
    for (let i = 0; i < count; i++) {
      const ing = ingredients[i % ingredients.length];
      const qty = ((i + 1) * 0.15);
      cost += ing.costPerUnit * qty;
    }
    return cost;
  };

  const filteredItems = items.filter(i => 
    i.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="h-full flex flex-col bg-card relative">
      <div className="p-4 border-b border-border flex justify-between gap-4 bg-muted/10 shrink-0">
        <div className="relative w-full sm:w-64">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <input 
            type="text" 
            placeholder="Search menu items..." 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9 pr-4 py-2 rounded-lg border border-border bg-background outline-none focus:border-primary text-sm font-medium w-full"
          />
        </div>
      </div>

      <div className="flex-1 overflow-auto p-4 sm:p-6">
        <div className="bg-background border border-border rounded-2xl shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm text-left whitespace-nowrap min-w-[800px]">
              <thead className="text-xs text-muted-foreground uppercase bg-muted/50 sticky top-0 z-10">
              <tr>
                <th className="px-5 py-4 font-bold">Menu Item</th>
                <th className="px-5 py-4 font-bold">Category</th>
                <th className="px-5 py-4 font-bold text-right">Selling Price</th>
                <th className="px-5 py-4 font-bold text-right">Recipe Cost</th>
                <th className="px-5 py-4 font-bold text-right">Gross Margin</th>
                <th className="px-5 py-4 font-bold">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {filteredItems.map((item) => {
                const category = categories.find(c => c.id === item.categoryId)?.name || 'Unknown';
                const sellPrice = parseFloat(item.price);
                const recipeCost = calculateItemCost(item.id);
                const marginAmount = sellPrice - recipeCost;
                const marginPct = sellPrice > 0 ? (marginAmount / sellPrice) * 100 : 0;

                const isLowMargin = marginPct < 30; // Anything below 30% is low margin
                const isHighMargin = marginPct >= 70; // High margin

                return (
                  <tr key={item.id} className="hover:bg-muted/30">
                    <td className="px-5 py-4 font-bold text-foreground">{item.name}</td>
                    <td className="px-5 py-4 text-xs text-muted-foreground font-medium">{category}</td>
                    <td className="px-5 py-4 font-black text-right text-foreground">Γé╣{sellPrice.toFixed(2)}</td>
                    <td className="px-5 py-4 font-black text-right text-red-600">Γé╣{recipeCost.toFixed(2)}</td>
                    <td className="px-5 py-4 text-right">
                      <div className="flex flex-col items-end">
                        <span className={`font-black ${isLowMargin ? 'text-red-600' : isHighMargin ? 'text-green-600' : 'text-blue-600'}`}>
                          {marginPct.toFixed(1)}%
                        </span>
                        <span className="text-xs font-medium text-muted-foreground">Γé╣{marginAmount.toFixed(2)}</span>
                      </div>
                    </td>
                    <td className="px-5 py-4">
                      {isLowMargin ? (
                        <span className="flex items-center gap-1.5 px-2 py-1 bg-red-100 text-red-700 text-xs font-bold rounded border border-red-200 w-max">
                          <TrendingDown className="w-3 h-3" /> Low Margin
                        </span>
                      ) : isHighMargin ? (
                        <span className="flex items-center gap-1.5 px-2 py-1 bg-green-100 text-green-700 text-xs font-bold rounded border border-green-200 w-max">
                          <TrendingUp className="w-3 h-3" /> Great Margin
                        </span>
                      ) : (
                        <span className="px-2 py-1 bg-blue-100 text-blue-700 text-xs font-bold rounded border border-blue-200 w-max">Healthy</span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { TrendingUp, TrendingDown, ShoppingCart, AlertTriangle, ArrowDownToLine, ArrowUpFromLine, FileText, Filter } from 'lucide-react';
import { useInventoryStore } from '../../../store/useInventoryStore';

const TYPE_CONFIG = {
  stock_in:  { label: 'Stock In',  color: 'bg-green-100 text-green-700 border-green-200',  icon: ArrowDownToLine,  iconColor: 'text-green-600' },
  stock_out: { label: 'Stock Out', color: 'bg-red-100 text-red-700 border-red-200',        icon: ArrowUpFromLine,  iconColor: 'text-red-600'   },
  po:        { label: 'PO',        color: 'bg-blue-100 text-blue-700 border-blue-200',     icon: ShoppingCart,     iconColor: 'text-blue-600'  },
};

const PO_STATUS = {
  Pending:  'bg-yellow-100 text-yellow-700 border-yellow-200',
  Ordered:  'bg-blue-100 text-blue-700 border-blue-200',
  Received: 'bg-green-100 text-green-700 border-green-200',
  Cancelled:'bg-red-100 text-red-700 border-red-200',
};

function formatDate(iso) {
  const d = new Date(iso);
  return d.toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' });
}

export default function StockLedgerTab() {
  const {
    transactions, purchaseOrders, ingredients, selectedOutlet,
    OUTLETS, getStock, updatePOStatus,
  } = useInventoryStore();

  const [activeSection, setActiveSection] = useState('overview'); // overview | ledger | po
  const [typeFilter, setTypeFilter] = useState('all');
  const [ingFilter, setIngFilter]   = useState('all');

  // ΓöÇΓöÇ Summary Calculations ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const stock = getStock(selectedOutlet);

  const totalIngredients = ingredients.length;
  const lowStockCount = ingredients.filter((ing) => (stock[ing.id] ?? 0) < ing.minStock).length;
  const criticalCount  = ingredients.filter((ing) => (stock[ing.id] ?? 0) < ing.minStock * 0.5).length;

  const totalStockValue = ingredients.reduce((sum, ing) => {
    return sum + (stock[ing.id] ?? 0) * ing.costPerUnit;
  }, 0);

  const todayTxns = transactions.filter((t) => {
    const d = new Date(t.date);
    const today = new Date();
    return d.toDateString() === today.toDateString();
  });
  const todayIn  = todayTxns.filter((t) => t.type === 'stock_in').reduce((s, t)  => s + t.qty, 0);
  const todayOut = todayTxns.filter((t) => t.type === 'stock_out').reduce((s, t) => s + t.qty, 0);

  const pendingPOs = purchaseOrders.filter((p) => p.status === 'Pending' || p.status === 'Ordered');

  // ΓöÇΓöÇ Filtered Transactions ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const filteredTxns = transactions
    .filter((t) => selectedOutlet === 'all' || t.outletId === selectedOutlet)
    .filter((t) => typeFilter === 'all' || t.type === typeFilter)
    .filter((t) => ingFilter === 'all' || t.ingredientId === ingFilter);

  // ΓöÇΓöÇ Filtered POs ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const filteredPOs = purchaseOrders.filter(
    (p) => selectedOutlet === 'all' || p.outletId === selectedOutlet
  );

  // ΓöÇΓöÇ Reports ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const getWastageSummary = useInventoryStore(state => state.getWastageSummary);
  const getDailyReport = useInventoryStore(state => state.getDailyReport);

  const wastageSummary = getWastageSummary(selectedOutlet);
  const totalWastageLoss = wastageSummary.reduce((sum, t) => sum + t.lossValue, 0);
  const [reportDate, setReportDate] = useState(new Date().toISOString().split('T')[0]);
  const dailyReport = getDailyReport(reportDate, selectedOutlet);

  return (
    <div className="h-full flex flex-col bg-background overflow-hidden">

      {/* Section Tabs */}
      <div className="bg-card border-b border-border px-4 flex gap-1 shrink-0 overflow-x-auto scrollbar-hide">
        {[
          { id: 'overview', label: 'Overview' },
          { id: 'ledger',   label: 'Transaction Ledger' },
          { id: 'po',       label: `Purchase Orders (${pendingPOs.length} Pending)` },
          { id: 'wastage',  label: 'Wastage Report' },
          { id: 'daily',    label: 'Daily Stock Report' },
        ].map((s) => (
          <button
            key={s.id}
            onClick={() => setActiveSection(s.id)}
            className={`py-3 px-4 text-sm font-bold border-b-2 whitespace-nowrap transition-colors ${
              activeSection === s.id
                ? 'border-primary text-primary'
                : 'border-transparent text-muted-foreground hover:text-foreground hover:border-border'
            }`}
          >
            {s.label}
          </button>
        ))}
      </div>

      <div className="flex-1 overflow-y-auto">

        {/* ΓòÉΓòÉΓòÉΓòÉ OVERVIEW ΓòÉΓòÉΓòÉΓòÉ */}
        {activeSection === 'overview' && (
          <div className="p-6 space-y-6">

            {/* KPI Cards */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              <div className="bg-card border border-border rounded-2xl p-5 shadow-sm">
                <p className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Total Stock Value</p>
                <h3 className="text-2xl font-black text-foreground">Γé╣{totalStockValue.toFixed(2)}</h3>
                <p className="text-xs text-muted-foreground mt-1 font-medium">{totalIngredients} ingredients tracked</p>
              </div>
              <div className={`bg-card border rounded-2xl p-5 shadow-sm ${criticalCount > 0 ? 'border-red-200' : 'border-border'}`}>
                <p className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Low Stock Alerts</p>
                <h3 className={`text-2xl font-black ${lowStockCount > 0 ? 'text-orange-600' : 'text-foreground'}`}>{lowStockCount}</h3>
                <p className="text-xs mt-1 font-bold text-red-600">{criticalCount} Critical</p>
              </div>
              <div className="bg-card border border-green-200 rounded-2xl p-5 shadow-sm">
                <p className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Today's Stock In</p>
                <h3 className="text-2xl font-black text-green-600">+{todayIn}</h3>
                <p className="text-xs text-muted-foreground mt-1 font-medium">{todayTxns.filter(t=>t.type==='stock_in').length} transactions</p>
              </div>
              <div className="bg-card border border-red-200 rounded-2xl p-5 shadow-sm">
                <p className="text-xs font-bold text-muted-foreground uppercase tracking-wider mb-2">Today's Stock Out</p>
                <h3 className="text-2xl font-black text-red-600">ΓêÆ{todayOut}</h3>
                <p className="text-xs text-muted-foreground mt-1 font-medium">{todayTxns.filter(t=>t.type==='stock_out').length} transactions</p>
              </div>
            </div>

            {/* Per-Ingredient Balance */}
            <div className="bg-card border border-border rounded-2xl overflow-hidden shadow-sm">
              <div className="p-4 border-b border-border bg-muted/20">
                <h3 className="font-black text-foreground">Current Stock Balance</h3>
                <p className="text-xs text-muted-foreground font-medium mt-0.5">
                  {OUTLETS[selectedOutlet] || 'All Outlets'} ΓÇö Live remaining quantities
                </p>
              </div>
              <div className="divide-y divide-border">
                {ingredients.map((ing) => {
                  const current  = stock[ing.id] ?? 0;
                  const isLow    = current < ing.minStock;
                  const isCrit   = current < ing.minStock * 0.5;
                  const pct      = Math.min(100, Math.round((current / (ing.minStock * 2)) * 100));
                  return (
                    <div key={ing.id} className="px-5 py-4">
                      <div className="flex items-center justify-between mb-1.5">
                        <div className="flex items-center gap-2">
                          <span className="font-bold text-sm text-foreground">{ing.name}</span>
                          {isCrit && <AlertTriangle className="w-3.5 h-3.5 text-red-500" />}
                        </div>
                        <span className={`font-black text-sm ${isCrit ? 'text-red-600' : isLow ? 'text-orange-500' : 'text-green-600'}`}>
                          {current} <span className="text-xs font-bold text-muted-foreground">{ing.unit}</span>
                          <span className="text-xs font-medium text-muted-foreground ml-2">/ min {ing.minStock}</span>
                        </span>
                      </div>
                      <div className="w-full bg-muted rounded-full h-2">
                        <div
                          className={`h-2 rounded-full transition-all ${isCrit ? 'bg-red-500' : isLow ? 'bg-orange-400' : 'bg-green-500'}`}
                          style={{ width: `${pct}%` }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Recent Transactions Preview */}
            <div className="bg-card border border-border rounded-2xl overflow-hidden shadow-sm">
              <div className="p-4 border-b border-border bg-muted/20 flex justify-between items-center">
                <h3 className="font-black text-foreground">Recent Transactions</h3>
                <button onClick={() => setActiveSection('ledger')} className="text-primary text-xs font-bold hover:underline">
                  View All ΓåÆ
                </button>
              </div>
              <div className="divide-y divide-border">
                {transactions.slice(0, 5).map((txn) => {
                  const ing = ingredients.find((i) => i.id === txn.ingredientId);
                  const cfg = TYPE_CONFIG[txn.type];
                  const Icon = cfg?.icon;
                  return (
                    <div key={txn.id} className="px-5 py-4 flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className={`w-9 h-9 rounded-xl flex items-center justify-center bg-muted`}>
                          {Icon && <Icon className={`w-4 h-4 ${cfg.iconColor}`} />}
                        </div>
                        <div>
                          <p className="font-bold text-sm text-foreground">{ing?.name || txn.ingredientId}</p>
                          <p className="text-xs text-muted-foreground">{txn.note} ΓÇó {OUTLETS[txn.outletId]}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className={`font-black text-sm ${txn.type === 'stock_in' ? 'text-green-600' : 'text-red-600'}`}>
                          {txn.type === 'stock_in' ? '+' : 'ΓêÆ'}{txn.qty} {ing?.unit}
                        </p>
                        <p className="text-xs text-muted-foreground">{formatDate(txn.date)}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        )}

        {/* ΓòÉΓòÉΓòÉΓòÉ LEDGER ΓòÉΓòÉΓòÉΓòÉ */}
        {activeSection === 'ledger' && (
          <div className="flex flex-col h-full">
            {/* Filter Bar */}
            <div className="p-4 border-b border-border bg-muted/10 shrink-0 flex flex-wrap gap-3 items-center">
              <Filter className="w-4 h-4 text-muted-foreground" />
              <select
                value={typeFilter}
                onChange={(e) => setTypeFilter(e.target.value)}
                className="px-3 py-2 rounded-lg border border-border bg-background outline-none focus:border-primary text-sm font-bold"
              >
                <option value="all">All Types</option>
                <option value="stock_in">Stock In</option>
                <option value="stock_out">Stock Out</option>
              </select>
              <select
                value={ingFilter}
                onChange={(e) => setIngFilter(e.target.value)}
                className="px-3 py-2 rounded-lg border border-border bg-background outline-none focus:border-primary text-sm font-bold"
              >
                <option value="all">All Ingredients</option>
                {ingredients.map((ing) => (
                  <option key={ing.id} value={ing.id}>{ing.name}</option>
                ))}
              </select>
              <span className="text-xs font-bold text-muted-foreground ml-auto">{filteredTxns.length} records</span>
            </div>

            <div className="flex-1 overflow-auto">
              <div className="overflow-x-auto min-h-0">
                <table className="w-full text-sm text-left whitespace-nowrap min-w-[1000px]">
                  <thead className="text-xs text-muted-foreground uppercase bg-muted/50 sticky top-0 z-10">
                  <tr>
                    <th className="px-5 py-4 font-bold">Txn ID</th>
                    <th className="px-5 py-4 font-bold">Date & Time</th>
                    <th className="px-5 py-4 font-bold">Type</th>
                    <th className="px-5 py-4 font-bold">Ingredient</th>
                    <th className="px-5 py-4 font-bold">Outlet</th>
                    <th className="px-5 py-4 font-bold text-right">Qty</th>
                    <th className="px-5 py-4 font-bold text-right">Balance After</th>
                    <th className="px-5 py-4 font-bold">Note / PO Ref</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {filteredTxns.map((txn) => {
                    const ing = ingredients.find((i) => i.id === txn.ingredientId);
                    const cfg = TYPE_CONFIG[txn.type];
                    return (
                      <tr key={txn.id} className="hover:bg-muted/30 transition-colors">
                        <td className="px-5 py-3 font-mono text-xs text-muted-foreground">{txn.id}</td>
                        <td className="px-5 py-3 text-xs font-medium text-muted-foreground whitespace-nowrap">{formatDate(txn.date)}</td>
                        <td className="px-5 py-3">
                          <span className={`flex items-center gap-1.5 px-2 py-1 rounded text-[11px] font-bold border w-max ${cfg?.color}`}>
                            {txn.type === 'stock_in' ? <ArrowDownToLine className="w-3 h-3" /> : <ArrowUpFromLine className="w-3 h-3" />}
                            {cfg?.label}
                          </span>
                        </td>
                        <td className="px-5 py-3 font-bold text-foreground">{ing?.name || txn.ingredientId}</td>
                        <td className="px-5 py-3 text-xs text-muted-foreground font-medium">{OUTLETS[txn.outletId]}</td>
                        <td className={`px-5 py-3 font-black text-right ${txn.type === 'stock_in' ? 'text-green-600' : 'text-red-600'}`}>
                          {txn.type === 'stock_in' ? '+' : 'ΓêÆ'}{txn.qty} {ing?.unit}
                        </td>
                        <td className="px-5 py-3 font-black text-right text-foreground">
                          {txn.balance} {ing?.unit}
                        </td>
                        <td className="px-5 py-3 text-xs text-muted-foreground">
                          <div>{txn.note}</div>
                          {txn.poRef && <span className="font-bold text-blue-600">{txn.poRef}</span>}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
        )}

        {/* ΓòÉΓòÉΓòÉΓòÉ PURCHASE ORDERS ΓòÉΓòÉΓòÉΓòÉ */}
        {activeSection === 'po' && (
          <div className="p-6 space-y-4">
            {filteredPOs.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-16 text-muted-foreground">
                <ShoppingCart className="w-12 h-12 mb-4 opacity-20" />
                <p className="font-bold">No Purchase Orders</p>
              </div>
            ) : (
              filteredPOs.map((po) => {
                const statusClass = PO_STATUS[po.status] || 'bg-muted text-foreground border-border';
                return (
                  <div key={po.id} className="bg-card border border-border rounded-2xl overflow-hidden shadow-sm">
                    <div className="px-5 py-4 flex items-center justify-between border-b border-border bg-muted/20">
                      <div className="flex items-center gap-3">
                        <FileText className="w-5 h-5 text-muted-foreground" />
                        <div>
                          <span className="font-black text-foreground">{po.id}</span>
                          <span className="ml-2 text-xs font-medium text-muted-foreground">{formatDate(po.date)}</span>
                        </div>
                        <span className={`text-xs font-bold px-2.5 py-1 rounded border ${statusClass}`}>{po.status}</span>
                      </div>
                      <div className="flex items-center gap-3">
                        <span className="text-xs text-muted-foreground font-medium">{OUTLETS[po.outletId]}</span>
                        <span className="font-black text-foreground">Γé╣{po.totalCost.toFixed(2)}</span>
                        {po.status !== 'Received' && po.status !== 'Cancelled' && (
                          <div className="flex gap-2">
                            {po.status === 'Pending' && (
                              <button
                                onClick={() => updatePOStatus(po.id, 'Ordered')}
                                className="text-xs font-bold px-3 py-1.5 bg-blue-100 text-blue-700 border border-blue-200 rounded-lg hover:bg-blue-200 transition-colors"
                              >
                                Mark Ordered
                              </button>
                            )}
                            <button
                              onClick={() => updatePOStatus(po.id, 'Received')}
                              className="text-xs font-bold px-3 py-1.5 bg-green-100 text-green-700 border border-green-200 rounded-lg hover:bg-green-200 transition-colors"
                            >
                              Mark Received
                            </button>
                          </div>
                        )}
                      </div>
                    </div>
                    <div className="p-4 space-y-2">
                      {po.items.map((item, idx) => {
                        const ing = ingredients.find((i) => i.id === item.ingredientId);
                        return (
                          <div key={idx} className="flex items-center justify-between text-sm">
                            <span className="font-medium text-foreground">{ing?.name || item.ingredientId}</span>
                            <div className="flex items-center gap-4 text-muted-foreground">
                              <span>{item.qty} {ing?.unit}</span>
                              <span className="font-bold text-foreground">Γé╣{(item.qty * item.costPerUnit).toFixed(2)}</span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                );
              })
            )}
          </div>
        )}

        {/* ΓòÉΓòÉΓòÉΓòÉ WASTAGE REPORT ΓòÉΓòÉΓòÉΓòÉ */}
        {activeSection === 'wastage' && (
          <div className="p-6 space-y-4">
            <div className="bg-red-50 border border-red-200 rounded-2xl p-5 shadow-sm flex items-center justify-between">
              <div>
                <p className="text-xs font-bold text-red-700 uppercase tracking-wider mb-1">Total Loss Value</p>
                <h3 className="text-2xl font-black text-red-800">Γé╣{totalWastageLoss.toFixed(2)}</h3>
              </div>
              <AlertTriangle className="w-8 h-8 text-red-500 opacity-50" />
            </div>

            {wastageSummary.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground">
                <AlertTriangle className="w-12 h-12 mx-auto mb-4 opacity-20" />
                <p className="font-bold">No Wastage Recorded</p>
              </div>
            ) : (
              <div className="bg-card border border-border rounded-2xl overflow-hidden shadow-sm">
                <div className="overflow-x-auto">
                  <table className="w-full text-sm text-left whitespace-nowrap min-w-[800px]">
                    <thead className="text-xs text-muted-foreground uppercase bg-muted/50 sticky top-0">
                    <tr>
                      <th className="px-5 py-4 font-bold">Date</th>
                      <th className="px-5 py-4 font-bold">Ingredient</th>
                      <th className="px-5 py-4 font-bold">Reason</th>
                      <th className="px-5 py-4 font-bold">Qty Lost</th>
                      <th className="px-5 py-4 font-bold text-right">Loss Value</th>
                      <th className="px-5 py-4 font-bold">Note</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border">
                    {wastageSummary.map((t) => (
                      <tr key={t.id} className="hover:bg-muted/30">
                        <td className="px-5 py-3 text-xs text-muted-foreground">{formatDate(t.date)}</td>
                        <td className="px-5 py-3 font-bold text-foreground">{t.ingredientName}</td>
                        <td className="px-5 py-3">
                          <span className={`text-xs font-bold px-2 py-1 rounded ${t.reason === 'damage' ? 'bg-red-100 text-red-700' : 'bg-orange-100 text-orange-700'}`}>
                            {t.reason}
                          </span>
                        </td>
                        <td className="px-5 py-3 font-bold text-red-600">{t.qty} {t.unit}</td>
                        <td className="px-5 py-3 font-black text-right text-red-600">Γé╣{t.lossValue.toFixed(2)}</td>
                        <td className="px-5 py-3 text-xs text-muted-foreground">{t.note}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
            )}
          </div>
        )}

        {/* ΓòÉΓòÉΓòÉΓòÉ DAILY STOCK REPORT ΓòÉΓòÉΓòÉΓòÉ */}
        {activeSection === 'daily' && (
          <div className="p-6 flex flex-col h-full space-y-4">
            <div className="flex items-center gap-4 bg-muted/20 p-4 rounded-xl border border-border shrink-0">
              <label className="text-sm font-bold text-muted-foreground">Report Date:</label>
              <input
                type="date"
                value={reportDate}
                onChange={(e) => setReportDate(e.target.value)}
                className="px-3 py-2 rounded-lg border border-border bg-background outline-none focus:border-primary text-sm font-bold"
              />
              <span className="text-xs text-muted-foreground ml-auto">Data for: {OUTLETS[selectedOutlet] || 'All Outlets'}</span>
            </div>

            <div className="flex-1 overflow-auto bg-card border border-border rounded-2xl shadow-sm">
              <div className="overflow-x-auto min-h-0">
                <table className="w-full text-sm text-left whitespace-nowrap min-w-[900px]">
                  <thead className="text-xs text-muted-foreground uppercase bg-muted/50 sticky top-0 z-10">
                  <tr>
                    <th className="px-5 py-4 font-bold">Ingredient</th>
                    <th className="px-5 py-4 font-bold text-right bg-muted/30">Opening Balance</th>
                    <th className="px-5 py-4 font-bold text-right text-green-700">Stock In (+)</th>
                    <th className="px-5 py-4 font-bold text-right text-blue-700">Consumed (-)</th>
                    <th className="px-5 py-4 font-bold text-right text-red-700">Wastage (-)</th>
                    <th className="px-5 py-4 font-bold text-right bg-muted/30">Closing Balance</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {dailyReport.map((row) => (
                    <tr key={row.ingredient.id} className="hover:bg-muted/30 transition-colors">
                      <td className="px-5 py-3">
                        <p className="font-bold text-foreground">{row.ingredient.name}</p>
                        <p className="text-[10px] text-muted-foreground">{row.ingredient.id}</p>
                      </td>
                      <td className="px-5 py-3 font-medium text-right bg-muted/10">{row.openingBalance} {row.ingredient.unit}</td>
                      <td className="px-5 py-3 font-bold text-right text-green-600">{row.totalIn > 0 ? `+${row.totalIn}` : '-'}</td>
                      <td className="px-5 py-3 font-bold text-right text-blue-600">{row.totalOut > row.wastage ? `-${row.totalOut - row.wastage}` : '-'}</td>
                      <td className="px-5 py-3 font-bold text-right text-red-600">{row.wastage > 0 ? `-${row.wastage}` : '-'}</td>
                      <td className="px-5 py-3 font-black text-right bg-muted/10">{row.closingBalance} {row.ingredient.unit}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { ArrowDownToLine, ArrowUpFromLine, AlertTriangle, X, Plus, Trash2, Zap } from 'lucide-react';
import { useInventoryStore } from '../../../store/useInventoryStore';

const REASON_OUT = [
  { value: 'consumption', label: 'Consumption', color: 'text-blue-600' },
  { value: 'wastage',     label: 'Wastage (Expired/Spoiled)', color: 'text-orange-600' },
  { value: 'damage',      label: 'Damage',      color: 'text-red-600' },
  { value: 'adjustment',  label: 'Adjustment',  color: 'text-purple-600' },
];

function AutoPOBanner({ poId, onDismiss }) {
  if (!poId) return null;
  return (
    <div className="fixed bottom-6 right-6 z-[200] bg-amber-50 border border-amber-300 rounded-2xl shadow-2xl p-4 max-w-sm animate-in slide-in-from-bottom-4 duration-300">
      <div className="flex items-start gap-3">
        <Zap className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
        <div className="flex-1">
          <p className="font-bold text-amber-900 text-sm">Auto-PO Generated!</p>
          <p className="text-xs text-amber-700 mt-0.5">Stock dropped below minimum threshold. A draft Purchase Order <strong>{poId}</strong> has been automatically created.</p>
        </div>
        <button onClick={onDismiss} className="p-1 hover:bg-amber-100 rounded transition-colors">
          <X className="w-4 h-4 text-amber-600" />
        </button>
      </div>
    </div>
  );
}

// ΓöÇΓöÇ Bulk Stock In Drawer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function BulkStockInDrawer({ onClose }) {
  const { ingredients, selectedOutlet, addBulkStockIn, OUTLETS } = useInventoryStore();
  const [rows, setRows] = useState([{ ingredientId: '', qty: '', note: '' }]);

  const addRow = () => setRows([...rows, { ingredientId: '', qty: '', note: '' }]);
  const removeRow = (idx) => setRows(rows.filter((_, i) => i !== idx));
  const updateRow = (idx, field, val) => setRows(rows.map((r, i) => i === idx ? { ...r, [field]: val } : r));

  const handleSubmit = (e) => {
    e.preventDefault();
    const valid = rows.filter((r) => r.ingredientId && parseFloat(r.qty) > 0);
    if (!valid.length) return;
    addBulkStockIn(valid, selectedOutlet);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex justify-end bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="absolute inset-0" onClick={onClose} />
      <div className="relative w-full max-w-xl bg-card h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
        <div className="p-6 border-b border-border bg-green-50">
          <div className="flex justify-between items-start">
            <div>
              <h3 className="text-xl font-black text-green-800">Bulk Stock In</h3>
              <p className="text-sm text-green-700 mt-1">
                Add multiple ingredients at once ΓÇö all quantities will accumulate on top of existing stock.
              </p>
              <p className="text-xs font-bold text-green-700 mt-1">Outlet: {OUTLETS[selectedOutlet]}</p>
            </div>
            <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-green-100 transition-colors"><X className="w-5 h-5 text-green-700" /></button>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-3">
          {/* Header */}
          <div className="grid grid-cols-[1fr_100px_1fr_32px] gap-2 text-xs font-bold text-muted-foreground uppercase tracking-wider px-1">
            <span>Ingredient</span><span className="text-right">Qty</span><span>Note</span><span />
          </div>

          {rows.map((row, idx) => {
            const ing = ingredients.find((i) => i.id === row.ingredientId);
            return (
              <div key={idx} className="grid grid-cols-[1fr_100px_1fr_32px] gap-2 items-center bg-muted/20 p-3 rounded-xl border border-border">
                <select
                  value={row.ingredientId}
                  onChange={(e) => updateRow(idx, 'ingredientId', e.target.value)}
                  className="w-full p-2 rounded-lg border border-border bg-background outline-none focus:border-primary text-sm font-medium"
                >
                  <option value="">SelectΓÇª</option>
                  {ingredients.map((i) => (
                    <option key={i.id} value={i.id}>{i.name} ({i.unit})</option>
                  ))}
                </select>
                <div className="relative">
                  <input
                    type="number" min="0.01" step="0.01"
                    value={row.qty}
                    onChange={(e) => updateRow(idx, 'qty', e.target.value)}
                    placeholder="0"
                    className="w-full p-2 rounded-lg border border-border bg-background outline-none focus:border-primary text-sm font-medium text-right pr-8"
                  />
                  {ing && <span className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] font-bold text-muted-foreground">{ing.unit}</span>}
                </div>
                <input
                  type="text"
                  value={row.note}
                  onChange={(e) => updateRow(idx, 'note', e.target.value)}
                  placeholder="NoteΓÇª"
                  className="w-full p-2 rounded-lg border border-border bg-background outline-none focus:border-primary text-sm font-medium"
                />
                <button onClick={() => removeRow(idx)} disabled={rows.length === 1} className="p-1.5 text-muted-foreground hover:text-red-500 hover:bg-red-50 rounded transition-colors disabled:opacity-30">
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            );
          })}

          <button onClick={addRow} className="w-full flex items-center justify-center gap-2 py-3 border-2 border-dashed border-border rounded-xl text-sm font-bold text-muted-foreground hover:border-primary hover:text-primary transition-colors">
            <Plus className="w-4 h-4" /> Add Another Ingredient
          </button>
        </div>

        <div className="p-6 border-t border-border bg-muted/10 grid grid-cols-2 gap-4">
          <button type="button" onClick={onClose} className="px-4 py-3 rounded-lg font-bold border border-border bg-background hover:bg-muted transition-colors">Cancel</button>
          <button onClick={handleSubmit} className="px-4 py-3 rounded-lg font-bold bg-green-600 text-white hover:bg-green-700 transition-colors shadow-sm">
            Confirm Stock In ({rows.filter(r => r.ingredientId && r.qty).length} items)
          </button>
        </div>
      </div>
    </div>
  );
}

// ΓöÇΓöÇ Single Stock Out Drawer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function StockOutDrawer({ onClose }) {
  const { ingredients, selectedOutlet, addStockOut, OUTLETS } = useInventoryStore();
  const [ingredientId, setIngredientId] = useState('');
  const [qty, setQty]    = useState('');
  const [reason, setReason] = useState('consumption');
  const [note, setNote]  = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    addStockOut(ingredientId, qty, selectedOutlet, note || REASON_OUT.find(r => r.value === reason)?.label, reason);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[100] flex justify-end bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="absolute inset-0" onClick={onClose} />
      <div className="relative w-full max-w-md bg-card h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
        <div className="p-6 border-b border-border bg-red-50">
          <div className="flex justify-between items-start">
            <div>
              <h3 className="text-xl font-black text-red-800">Stock Out</h3>
              <p className="text-sm text-red-700 mt-1">Deduct stock and categorize the reason for accurate reporting.</p>
            </div>
            <button onClick={onClose} className="p-1.5 rounded-lg hover:bg-red-100 transition-colors"><X className="w-5 h-5 text-red-700" /></button>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 space-y-5">
          <div className="p-3 rounded-lg border border-border bg-muted/40 text-sm font-bold">{OUTLETS[selectedOutlet]}</div>

          <div className="space-y-2">
            <label className="text-sm font-bold text-muted-foreground">Ingredient</label>
            <select required value={ingredientId} onChange={(e) => setIngredientId(e.target.value)}
              className="w-full p-3 rounded-lg border border-border bg-background outline-none focus:border-primary font-medium">
              <option value="">Select ingredientΓÇª</option>
              {ingredients.map((ing) => <option key={ing.id} value={ing.id}>{ing.name} ({ing.unit})</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-bold text-muted-foreground">Reason for Deduction</label>
            <div className="grid grid-cols-2 gap-2">
              {REASON_OUT.map((r) => (
                <button key={r.value} type="button" onClick={() => setReason(r.value)}
                  className={`p-3 rounded-xl border-2 text-left transition-all ${reason === r.value ? 'border-primary bg-primary/5' : 'border-border bg-background hover:border-border'}`}>
                  <p className={`text-xs font-black ${reason === r.value ? 'text-primary' : r.color}`}>{r.label}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-bold text-muted-foreground">Quantity {ingredientId && `(${ingredients.find(i=>i.id===ingredientId)?.unit})`}</label>
            <input type="number" required min="0.01" step="0.01" value={qty} onChange={(e) => setQty(e.target.value)}
              placeholder="Enter quantity"
              className="w-full p-3 rounded-lg border border-border bg-background outline-none focus:border-primary font-medium" />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-bold text-muted-foreground">Note (optional)</label>
            <input type="text" value={note} onChange={(e) => setNote(e.target.value)}
              placeholder="e.g., End-of-day count, Expired batch"
              className="w-full p-3 rounded-lg border border-border bg-background outline-none focus:border-primary font-medium" />
          </div>

          <div className="bg-amber-50 border border-amber-200 rounded-xl p-3">
            <p className="text-xs font-bold text-amber-800">ΓÜí If stock drops below minimum threshold, a draft Purchase Order will be auto-generated.</p>
          </div>
        </form>

        <div className="p-6 border-t border-border bg-muted/10 grid grid-cols-2 gap-4">
          <button type="button" onClick={onClose} className="px-4 py-3 rounded-lg font-bold border border-border bg-background hover:bg-muted transition-colors">Cancel</button>
          <button onClick={handleSubmit} className="px-4 py-3 rounded-lg font-bold bg-red-600 text-white hover:bg-red-700 transition-colors shadow-sm">Deduct Stock</button>
        </div>
      </div>
    </div>
  );
}

// ΓöÇΓöÇ Main StockLevelsTab ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
export default function StockLevelsTab() {
  const { ingredients, selectedOutlet, getStock, OUTLETS, lastAutoPO, clearLastAutoPO } = useInventoryStore();
  const [drawer, setDrawer] = useState(null); // 'bulk-in' | 'out' | null

  const stock = getStock(selectedOutlet);

  const handleClose = () => {
    setDrawer(null);
  };

  return (
    <div className="h-full flex flex-col bg-card relative">
      <div className="p-4 border-b border-border bg-muted/10 shrink-0 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
        <div>
          <h2 className="text-lg font-black">{selectedOutlet === 'all' ? 'Global Stock Levels' : OUTLETS[selectedOutlet]}</h2>
          <p className="text-xs text-muted-foreground mt-0.5">Live stock balances ΓÇó Click Stock In/Out to adjust</p>
        </div>
        <div className="flex gap-2 w-full sm:w-auto">
          <button onClick={() => setDrawer('bulk-in')}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white font-bold rounded-lg shadow-sm hover:bg-green-700 transition-colors text-sm">
            <ArrowDownToLine className="w-4 h-4" /> Bulk Stock In
          </button>
          <button onClick={() => setDrawer('out')}
            className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2 bg-red-600 text-white font-bold rounded-lg shadow-sm hover:bg-red-700 transition-colors text-sm">
            <ArrowUpFromLine className="w-4 h-4" /> Stock Out
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-auto">
        <div className="overflow-x-auto min-h-0">
          <table className="w-full text-sm text-left whitespace-nowrap min-w-[800px]">
            <thead className="text-xs text-muted-foreground uppercase bg-muted/50 sticky top-0 z-10">
            <tr>
              <th className="px-6 py-4 font-bold">Ingredient</th>
              <th className="px-6 py-4 font-bold">Category</th>
              <th className="px-6 py-4 font-bold text-right">Current Stock</th>
              <th className="px-6 py-4 font-bold text-right">Min Threshold</th>
              <th className="px-6 py-4 font-bold text-right">Est. Value</th>
              <th className="px-6 py-4 font-bold">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {ingredients.map((ing) => {
              const current = stock[ing.id] ?? 0;
              const isLow   = current < ing.minStock;
              const isCrit  = current < ing.minStock * 0.5;
              const value   = current * ing.costPerUnit;
              return (
                <tr key={ing.id} className={`hover:bg-muted/30 transition-colors ${isCrit ? 'bg-red-50/40' : ''}`}>
                  <td className="px-6 py-4">
                    <p className="font-bold text-foreground">{ing.name}</p>
                    <p className="text-[10px] font-bold text-muted-foreground">{ing.id}</p>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2 py-1 bg-muted rounded text-xs font-bold text-muted-foreground">{ing.category}</span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <span className={`text-xl font-black ${isCrit ? 'text-red-600' : isLow ? 'text-orange-500' : 'text-foreground'}`}>{current}</span>
                    <span className="text-xs font-bold text-muted-foreground ml-1">{ing.unit}</span>
                  </td>
                  <td className="px-6 py-4 text-right text-muted-foreground font-medium">{ing.minStock} {ing.unit}</td>
                  <td className="px-6 py-4 text-right font-bold text-foreground">Γé╣{value.toFixed(2)}</td>
                  <td className="px-6 py-4">
                    {isCrit ? (
                      <span className="flex items-center gap-1.5 px-2 py-1 bg-red-100 text-red-700 text-xs font-bold rounded border border-red-200 w-max">
                        <AlertTriangle className="w-3.5 h-3.5" /> Critical
                      </span>
                    ) : isLow ? (
                      <span className="flex items-center gap-1.5 px-2 py-1 bg-orange-100 text-orange-700 text-xs font-bold rounded border border-orange-200 w-max">
                        <AlertTriangle className="w-3.5 h-3.5" /> Low Stock
                      </span>
                    ) : (
                      <span className="px-2 py-1 bg-green-100 text-green-700 text-xs font-bold rounded border border-green-200 w-max">Healthy</span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        </div>
      </div>

      {drawer === 'bulk-in' && <BulkStockInDrawer onClose={handleClose} />}
      {drawer === 'out'     && <StockOutDrawer onClose={handleClose} />}
      <AutoPOBanner poId={lastAutoPO} onDismiss={clearLastAutoPO} />
    </div>
  );
}

import { useState } from 'react';
import { Plus, Edit2, Trash2, ChevronDown, ChevronRight, Check } from 'lucide-react';
import { useMenuStore } from '../../../store/useMenuStore';
import { AddonGroupModal, AddonItemModal } from './modals/FormModals';

export default function AddonManager({ itemId }) {
  const {
    addonGroups, addAddonGroup, updateAddonGroup, deleteAddonGroup,
    addonItems, addAddonItem, updateAddonItem, deleteAddonItem,
    itemAddonLinks, setItemAddonLinks,
    selectedCategoryId,
  } = useMenuStore();

  const link = itemAddonLinks[itemId] || { linked: [], applyToCategory: false };
  const [groupModal, setGroupModal] = useState(null);
  const [itemModal, setItemModal] = useState(null);
  const [expanded, setExpanded] = useState({});
  const [showPicker, setShowPicker] = useState(false);

  const toggleLink = (groupId) => {
    const already = link.linked.includes(groupId);
    setItemAddonLinks(itemId, {
      ...link,
      linked: already ? link.linked.filter(g => g !== groupId) : [...link.linked, groupId],
    });
  };

  const linkedGroups = addonGroups.filter(g => link.linked.includes(g.id));

  return (
    <div className="space-y-3">
      {/* Link Groups */}
      <div>
        <div className="flex items-center justify-between mb-1.5">
          <span className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Linked Addon Groups</span>
          <div className="flex gap-1">
            <button
              onClick={() => setShowPicker(!showPicker)}
              className="flex items-center gap-1 px-2 py-1 text-xs font-semibold bg-muted text-foreground rounded-md hover:bg-muted/80 transition-colors"
            >
              Link Groups
            </button>
            <button
              onClick={() => setGroupModal({ mode: 'add' })}
              className="flex items-center gap-1 px-2 py-1 text-xs font-semibold bg-primary/10 text-primary rounded-md hover:bg-primary/20 transition-colors"
            >
              <Plus className="w-3 h-3" /> New
            </button>
          </div>
        </div>

        {/* Group picker dropdown */}
        {showPicker && (
          <div className="border border-border rounded-lg overflow-hidden mb-2">
            {addonGroups.map(g => (
              <label key={g.id} className="flex items-center gap-2 px-3 py-1.5 cursor-pointer hover:bg-muted/50 border-b border-border/50 last:border-0">
                <div
                  onClick={() => toggleLink(g.id)}
                  className={`w-4 h-4 rounded border flex items-center justify-center transition-colors cursor-pointer ${
                    link.linked.includes(g.id) ? 'bg-primary border-primary' : 'border-border'
                  }`}
                >
                  {link.linked.includes(g.id) && <Check className="w-2.5 h-2.5 text-white" />}
                </div>
                <span className="text-xs font-medium text-foreground">{g.name}</span>
                <span className="ml-auto text-[10px] text-muted-foreground">min {g.min} / max {g.max}</span>
              </label>
            ))}
          </div>
        )}

        {/* Apply to category checkbox */}
        <label className="flex items-center gap-2 cursor-pointer mb-2">
          <div
            onClick={() => setItemAddonLinks(itemId, { ...link, applyToCategory: !link.applyToCategory })}
            className={`w-4 h-4 rounded border flex items-center justify-center transition-colors cursor-pointer ${
              link.applyToCategory ? 'bg-primary border-primary' : 'border-border'
            }`}
          >
            {link.applyToCategory && <Check className="w-2.5 h-2.5 text-white" />}
          </div>
          <span className="text-xs text-muted-foreground">Apply to full category</span>
        </label>
      </div>

      {/* Linked groups list */}
      {linkedGroups.length === 0 ? (
        <div className="border border-dashed border-border rounded-xl py-8 flex flex-col items-center justify-center text-center px-4 bg-muted/10">
          <div className="w-10 h-10 bg-primary/10 text-primary rounded-full flex items-center justify-center mb-3">
            <Plus className="w-5 h-5" />
          </div>
          <p className="text-sm font-bold text-foreground mb-1">No addons linked</p>
          <p className="text-xs text-muted-foreground max-w-[200px]">Link existing addon groups like "Extra Toppings" or create a new one.</p>
        </div>
      ) : (
        <div className="space-y-1.5">
          {linkedGroups.map(group => {
            const groupItems = addonItems.filter(ai => ai.groupId === group.id);
            const isOpen = expanded[group.id];
            return (
              <div key={group.id} className="border border-border rounded-lg overflow-hidden">
                {/* Group header */}
                <div className="flex items-center gap-2 px-3 py-2 bg-muted/30 cursor-pointer" onClick={() => setExpanded(p => ({ ...p, [group.id]: !p[group.id] }))}>
                  {isOpen ? <ChevronDown className="w-3 h-3 text-muted-foreground" /> : <ChevronRight className="w-3 h-3 text-muted-foreground" />}
                  <span className="text-xs font-semibold text-foreground flex-1">{group.name}</span>
                  <span className="text-[10px] text-muted-foreground">min {group.min} / max {group.max}</span>
                  <button
                    onClick={(e) => { e.stopPropagation(); setGroupModal({ mode: 'edit', group }); }}
                    className="p-0.5 rounded hover:text-primary text-muted-foreground transition-colors"
                  >
                    <Edit2 className="w-3 h-3" />
                  </button>
                  <button
                    onClick={(e) => { e.stopPropagation(); deleteAddonGroup(group.id); }}
                    className="p-0.5 rounded hover:text-red-500 text-muted-foreground transition-colors"
                  >
                    <Trash2 className="w-3 h-3" />
                  </button>
                </div>

                {/* Addon items */}
                {isOpen && (
                  <div>
                    {groupItems.map(ai => (
                      <div key={ai.id} className="flex items-center gap-2 px-4 py-1.5 border-t border-border/50">
                        <span className="text-xs text-foreground flex-1">{ai.name}</span>
                        <span className="text-xs font-semibold text-foreground">Γé╣{ai.price}</span>
                        <button onClick={() => setItemModal({ mode: 'edit', item: ai, groupId: group.id })} className="p-0.5 text-muted-foreground hover:text-primary transition-colors">
                          <Edit2 className="w-3 h-3" />
                        </button>
                        <button onClick={() => deleteAddonItem(ai.id)} className="p-0.5 text-muted-foreground hover:text-red-500 transition-colors">
                          <Trash2 className="w-3 h-3" />
                        </button>
                      </div>
                    ))}
                    <button
                      onClick={() => setItemModal({ mode: 'add', groupId: group.id })}
                      className="flex items-center gap-1 w-full px-4 py-1.5 text-xs text-primary hover:bg-primary/5 transition-colors border-t border-border/50"
                    >
                      <Plus className="w-3 h-3" /> Add item
                    </button>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Modals */}
      {groupModal?.mode === 'add' && (
        <AddonGroupModal onSave={(d) => addAddonGroup(d)} onClose={() => setGroupModal(null)} />
      )}
      {groupModal?.mode === 'edit' && (
        <AddonGroupModal initial={groupModal.group} onSave={(d) => updateAddonGroup(groupModal.group.id, d)} onClose={() => setGroupModal(null)} />
      )}
      {itemModal?.mode === 'add' && (
        <AddonItemModal groupId={itemModal.groupId} onSave={(d) => addAddonItem(d)} onClose={() => setItemModal(null)} />
      )}
      {itemModal?.mode === 'edit' && (
        <AddonItemModal initial={itemModal.item} groupId={itemModal.groupId} onSave={(d) => updateAddonItem(itemModal.item.id, d)} onClose={() => setItemModal(null)} />
      )}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { useMenuStore } from '../../../store/useMenuStore';
import { Search, Save, X, Edit3, ArrowUpDown } from 'lucide-react';

export default function BulkEditGrid({ onClose }) {
  const { items, categories, updateItem, setHasUnsyncedChanges } = useMenuStore();
  const [search, setSearch] = useState('');
  const [filterCat, setFilterCat] = useState('All');

  // We will maintain a local state for edits to avoid brutal re-renders on every keystroke
  const [edits, setEdits] = useState({});

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      if (filterCat !== 'All' && item.categoryId !== filterCat) return false;
      if (search && !item.name.toLowerCase().includes(search.toLowerCase())) return false;
      return true;
    });
  }, [items, search, filterCat]);

  const handleEdit = (id, field, value) => {
    setEdits(prev => ({
      ...prev,
      [id]: {
        ...(prev[id] || {}),
        [field]: value
      }
    }));
  };

  const handleSave = () => {
    Object.entries(edits).forEach(([id, changes]) => {
      updateItem(id, changes);
    });
    setHasUnsyncedChanges(true);
    setEdits({});
  };

  const hasChanges = Object.keys(edits).length > 0;

  return (
    <div className="flex flex-col h-full bg-background absolute inset-0 z-40">
      {/* Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between px-4 md:px-6 py-3 md:py-4 bg-card border-b border-border shrink-0 gap-3">
        <div className="flex items-center gap-2 md:gap-3">
          <div className="w-8 h-8 md:w-10 md:h-10 bg-primary/10 text-primary rounded-lg flex items-center justify-center shrink-0">
            <Edit3 className="w-4 h-4 md:w-5 md:h-5" />
          </div>
          <div>
            <h2 className="text-sm md:text-base font-bold text-foreground">Bulk Edit Items</h2>
            <p className="text-[10px] md:text-xs text-muted-foreground hidden sm:block">Rapidly update pricing, markups, and stock status across your menu.</p>
          </div>
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          <button onClick={onClose} className="flex-1 sm:flex-initial px-3 md:px-4 py-2 border border-border rounded-lg text-xs md:text-sm font-semibold hover:bg-muted transition-colors whitespace-nowrap">
            Exit
          </button>
          <button 
            onClick={handleSave}
            disabled={!hasChanges}
            className={`flex-1 sm:flex-initial flex items-center justify-center gap-1.5 px-4 md:px-6 py-2 rounded-lg text-xs md:text-sm font-bold transition-all shadow-md whitespace-nowrap ${
              hasChanges ? 'bg-primary text-primary-foreground hover:bg-primary/90 hover:-translate-y-0.5' : 'bg-muted text-muted-foreground opacity-60 cursor-not-allowed shadow-none'
            }`}
          >
            <Save className="w-3.5 h-3.5" /> Save {Object.keys(edits).length > 0 ? Object.keys(edits).length : ''}
          </button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-2 md:gap-3 px-4 md:px-6 py-2 md:py-3 border-b border-border bg-muted/20 shrink-0">
        <div className="relative flex-1 min-w-[150px]">
          <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <input 
            type="text" 
            placeholder="Search items..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 bg-background border border-border rounded-lg text-xs md:text-sm outline-none focus:border-primary transition-colors"
          />
        </div>
        <select
          value={filterCat}
          onChange={(e) => setFilterCat(e.target.value)}
          className="px-2 md:px-3 py-2 bg-background border border-border rounded-lg text-xs md:text-sm outline-none focus:border-primary transition-colors cursor-pointer w-[120px] md:w-auto"
        >
          <option value="All">All Categories</option>
          {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
        </select>

        {hasChanges && (
          <span className="ml-auto text-xs font-semibold text-orange-500 bg-orange-50 px-2.5 py-1 rounded-full animate-pulse">
            Unsaved changes present
          </span>
        )}
      </div>

      {/* Data Grid */}
      <div className="flex-1 overflow-auto custom-scrollbar">
        <table className="w-full text-sm text-left">
          <thead className="text-xs text-muted-foreground bg-muted/50 uppercase sticky top-0 z-10 backdrop-blur-sm">
            <tr>
              <th className="px-6 py-3 font-semibold border-b border-border/50">Item Name</th>
              <th className="px-6 py-3 font-semibold border-b border-border/50">Category</th>
              <th className="px-6 py-3 font-semibold border-b border-border/50">Base Price (Γé╣)</th>
              <th className="px-6 py-3 font-semibold border-b border-border/50 text-orange-600">Swiggy Markup (%)</th>
              <th className="px-6 py-3 font-semibold border-b border-border/50 text-red-600">Zomato Markup (%)</th>
              <th className="px-6 py-3 font-semibold border-b border-border/50 text-center">In Stock</th>
            </tr>
          </thead>
          <tbody>
            {filteredItems.map(item => {
              const currentVals = edits[item.id] || {};
              const price = currentVals.price !== undefined ? currentVals.price : item.price;
              const swiggy = currentVals.swiggyMarkup !== undefined ? currentVals.swiggyMarkup : (item.swiggyMarkup || '0');
              const zomato = currentVals.zomatoMarkup !== undefined ? currentVals.zomatoMarkup : (item.zomatoMarkup || '0');
              const inStock = currentVals.inStock !== undefined ? currentVals.inStock : item.inStock;
              const catName = categories.find(c => c.id === item.categoryId)?.name || 'Unknown';

              const isEdited = (field) => currentVals[field] !== undefined && currentVals[field] !== item[field];

              return (
                <tr key={item.id} className="border-b border-border/50 hover:bg-muted/30 transition-colors">
                  <td className="px-6 py-2.5 font-semibold text-foreground">{item.name}</td>
                  <td className="px-6 py-2.5 text-muted-foreground text-xs">{catName}</td>

                  <td className="px-6 py-2.5">
                    <input 
                      type="number" 
                      value={price} 
                      onChange={(e) => handleEdit(item.id, 'price', e.target.value)}
                      className={`w-24 px-2 py-1.5 rounded outline-none font-bold text-foreground border transition-colors ${isEdited('price') ? 'bg-orange-50 border-orange-200 text-orange-700' : 'bg-transparent border-transparent hover:border-border focus:border-primary focus:bg-background'}`}
                    />
                  </td>

                  <td className="px-6 py-2.5">
                    <div className="relative">
                      <input 
                        type="number" 
                        value={swiggy} 
                        onChange={(e) => handleEdit(item.id, 'swiggyMarkup', e.target.value)}
                        className={`w-24 px-2 py-1.5 rounded outline-none font-bold text-foreground border transition-colors ${isEdited('swiggyMarkup') ? 'bg-orange-50 border-orange-200 text-orange-700' : 'bg-transparent border-transparent hover:border-border focus:border-orange-400 focus:bg-background'}`}
                      />
                    </div>
                  </td>

                  <td className="px-6 py-2.5">
                    <input 
                      type="number" 
                      value={zomato} 
                      onChange={(e) => handleEdit(item.id, 'zomatoMarkup', e.target.value)}
                      className={`w-24 px-2 py-1.5 rounded outline-none font-bold text-foreground border transition-colors ${isEdited('zomatoMarkup') ? 'bg-orange-50 border-orange-200 text-orange-700' : 'bg-transparent border-transparent hover:border-border focus:border-red-400 focus:bg-background'}`}
                    />
                  </td>

                  <td className="px-6 py-2.5 text-center">
                    <button
                      onClick={() => handleEdit(item.id, 'inStock', !inStock)}
                      className={`px-3 py-1.5 rounded text-xs font-bold transition-colors ${
                        inStock ? 'bg-green-50 text-green-700 hover:bg-red-50 hover:text-red-600' : 'bg-red-50 text-red-600 hover:bg-green-50 hover:text-green-700'
                      } ${isEdited('inStock') ? 'ring-2 ring-orange-400' : ''}`}
                    >
                      {inStock ? 'In Stock' : 'OOS'}
                    </button>
                  </td>
                </tr>
              );
            })}

            {filteredItems.length === 0 && (
              <tr>
                <td colSpan={6} className="px-6 py-10 text-center text-muted-foreground">
                  No items match your search or filter.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Plus, Edit2, Trash2, ToggleLeft, ToggleRight, ChevronUp, ChevronDown, MoreVertical, GripVertical, Search } from 'lucide-react';
import { useMenuStore } from '../../../store/useMenuStore';
import { CategoryModal, ConfirmModal } from './modals/FormModals';
import { getCategoryTax, totalRate } from '../../../utils/taxUtils';

import { DndContext, closestCenter, KeyboardSensor, PointerSensor, useSensor, useSensors } from '@dnd-kit/core';
import { arrayMove, SortableContext, sortableKeyboardCoordinates, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { restrictToVerticalAxis, restrictToParentElement } from '@dnd-kit/modifiers';
import { CSS } from '@dnd-kit/utilities';

function SortableCategoryItem({ cat, isSelected, itemCount, allActive, onSelect, onEdit, onDelete, onMove, onToggle, openMenuId, setOpenMenuId }) {
  const { taxes } = useMenuStore();
  const count = itemCount(cat.id);
  const isAllActive = allActive(cat.id);

  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: cat.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: (isDragging || openMenuId === cat.id) ? 50 : 1,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      onClick={() => onSelect(cat.id)}
      className={`group px-4 py-3 cursor-pointer transition-colors border-b border-border/50 relative bg-card ${
        isSelected ? 'bg-primary/5' : 'hover:bg-muted/50'
      } ${isDragging ? 'shadow-xl border-primary/50' : ''}`}
    >
      <div className="flex items-center gap-2.5">
        <div {...attributes} {...listeners} className="cursor-grab active:cursor-grabbing p-1 -ml-2 text-muted-foreground hover:text-foreground opacity-50 hover:opacity-100 transition-opacity">
          <GripVertical className="w-4 h-4" />
        </div>
        <span className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: cat.color || '#6366f1' }} />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5">
            <p className={`text-sm font-semibold truncate ${isSelected ? 'text-primary' : 'text-foreground'}`}>{cat.name}</p>
            {(() => { const t = getCategoryTax(cat.id, taxes); return t ? <span className="text-[10px] font-bold bg-green-50 text-green-700 px-1.5 py-0.5 rounded shrink-0">{totalRate(t)}%</span> : null; })()}
          </div>
          <p className="text-xs text-muted-foreground">{count} items {!cat.active && '┬╖ Hidden'}</p>
        </div>
      </div>

      {/* Actions */}
      <div className="flex items-center gap-1 mt-2 md:opacity-0 md:group-hover:opacity-100 transition-opacity relative">
        <button
          onClick={(e) => { e.stopPropagation(); onToggle(cat.id, !isAllActive); }}
          title={isAllActive ? 'Mark all Out of Stock' : 'Mark all In Stock'}
          className={`flex items-center gap-1 px-2 py-1 rounded text-xs font-semibold transition-colors flex-1 justify-center ${
            isAllActive ? 'bg-green-50 text-green-700 hover:bg-red-50 hover:text-red-600' : 'bg-red-50 text-red-600 hover:bg-green-50 hover:text-green-700'
          }`}
        >
          {isAllActive ? <ToggleRight className="w-3.5 h-3.5" /> : <ToggleLeft className="w-3.5 h-3.5" />}
          All
        </button>
        <button
          onClick={(e) => { 
            e.stopPropagation(); 
            setOpenMenuId(openMenuId === cat.id ? null : cat.id); 
          }}
          className={`p-1.5 rounded transition-colors ${openMenuId === cat.id ? 'bg-muted text-foreground' : 'hover:bg-muted text-muted-foreground'}`}
        >
          <MoreVertical className="w-3.5 h-3.5" />
        </button>

        {openMenuId === cat.id && (
          <>
            <div className="fixed inset-0 z-40" onClick={(e) => { e.stopPropagation(); setOpenMenuId(null); }} />
            <div className="absolute right-0 top-full mt-1 w-32 bg-card border border-border rounded-lg shadow-xl py-1 z-50 animate-in fade-in zoom-in-95 duration-100">
              <button onClick={(e) => { e.stopPropagation(); onMove(cat.id, 'up'); setOpenMenuId(null); }} className="w-full flex items-center gap-2 px-3 py-1.5 text-xs hover:bg-muted text-foreground">
                <ChevronUp className="w-3.5 h-3.5 text-muted-foreground" /> Move Up
              </button>
              <button onClick={(e) => { e.stopPropagation(); onMove(cat.id, 'down'); setOpenMenuId(null); }} className="w-full flex items-center gap-2 px-3 py-1.5 text-xs hover:bg-muted text-foreground">
                <ChevronDown className="w-3.5 h-3.5 text-muted-foreground" /> Move Down
              </button>
              <div className="h-px bg-border my-1" />
              <button onClick={(e) => { e.stopPropagation(); onEdit(cat); setOpenMenuId(null); }} className="w-full flex items-center gap-2 px-3 py-1.5 text-xs hover:bg-muted text-foreground">
                <Edit2 className="w-3.5 h-3.5 text-muted-foreground" /> Edit
              </button>
              <button onClick={(e) => { e.stopPropagation(); onDelete(cat); setOpenMenuId(null); }} className="w-full flex items-center gap-2 px-3 py-1.5 text-xs hover:bg-red-50 text-red-600">
                <Trash2 className="w-3.5 h-3.5" /> Delete
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

export default function CategoryList({ onMobileSelect }) {
  const {
    categories, addCategory, updateCategory, deleteCategory, bulkToggleCategory,
    selectedCategoryId, setSelectedCategoryId, items, moveCategory, reorderCategory
  } = useMenuStore();

  const [modal, setModal] = useState(null);
  const [openMenuId, setOpenMenuId] = useState(null);
  const [search, setSearch] = useState('');

  const itemCount = (catId) => items.filter(i => i.categoryId === catId).length;
  const allActive = (catId) => items.filter(i => i.categoryId === catId).every(i => i.inStock);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (active.id !== over?.id) {
      reorderCategory(active.id, over.id);
    }
  };

  return (
    <div className="w-full md:w-56 md:shrink-0 md:border-r border-border bg-card flex flex-col h-full">
      {/* Header */}
      <div className="flex flex-col border-b border-border">
        <div className="flex items-center justify-between px-4 py-3">
          <span className="text-sm font-bold uppercase tracking-wider text-muted-foreground">Categories</span>
          <button
            onClick={() => setModal({ mode: 'add' })}
            className="p-1.5 rounded-md bg-primary/10 text-primary hover:bg-primary hover:text-primary-foreground transition-colors"
          >
            <Plus className="w-4 h-4" />
          </button>
        </div>
        <div className="px-4 pb-3 relative">
          <Search className="w-3.5 h-3.5 absolute left-6 top-1/2 -translate-y-1/2 text-muted-foreground pb-3" style={{ top: 'calc(50% - 6px)' }} />
          <input
            type="text"
            placeholder="Search categories..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-7 pr-3 py-1.5 bg-muted/50 border border-border rounded-md text-xs outline-none focus:border-primary transition-colors"
          />
        </div>
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto py-1 custom-scrollbar">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragEnd={handleDragEnd}
          modifiers={[restrictToVerticalAxis, restrictToParentElement]}
        >
          <SortableContext
            items={categories.map(c => c.id)}
            strategy={verticalListSortingStrategy}
          >
            {categories.filter(c => !search || c.name.toLowerCase().includes(search.toLowerCase())).map(cat => (
              <SortableCategoryItem
                key={cat.id}
                cat={cat}
                isSelected={cat.id === selectedCategoryId}
                itemCount={itemCount}
                allActive={allActive}
                onSelect={(id) => { setSelectedCategoryId(id); onMobileSelect?.(); }}
                onEdit={(c) => setModal({ mode: 'edit', cat: c })}
                onDelete={(c) => setModal({ mode: 'delete', cat: c })}
                onMove={moveCategory}
                onToggle={bulkToggleCategory}
                openMenuId={openMenuId}
                setOpenMenuId={setOpenMenuId}
              />
            ))}
          </SortableContext>
        </DndContext>
      </div>

      {/* Modals */}
      {modal?.mode === 'add' && (
        <CategoryModal onSave={(data, timing) => addCategory(data, timing)} onClose={() => setModal(null)} />
      )}
      {modal?.mode === 'edit' && (
        <CategoryModal initial={modal.cat} onSave={(data, timing) => updateCategory(modal.cat.id, data, timing)} onClose={() => setModal(null)} />
      )}
      {modal?.mode === 'delete' && (
        <ConfirmModal 
          title="Delete Category" 
          message={`Are you sure you want to delete "${modal.cat.name}"? All items inside will lose their category association.`} 
          onConfirm={() => deleteCategory(modal.cat.id)} 
          onClose={() => setModal(null)} 
        />
      )}
    </div>
  );
}

