            placeholder="Please Enter terms and conditions: English"
            rows={5}
            className="w-full bg-background border border-border rounded-lg px-4 py-3 text-sm font-medium outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-colors resize-y"
          />
        </div>
      </Section>

      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Action Buttons ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="flex items-center justify-end gap-3 pt-2 pb-6">
        <button onClick={onBack} className="px-6 py-2.5 text-sm font-bold text-destructive hover:bg-destructive/10 rounded-lg transition-colors">
          Discard changes
        </button>
        <button className="flex items-center gap-2 px-6 py-2.5 bg-primary text-primary-foreground rounded-lg text-sm font-bold hover:bg-primary/90 transition-colors shadow-sm">
          <Save className="w-4 h-4" />
          Save
        </button>
      </div>

      {/* ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ Select Categories / Items Modal ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <SelectCategoriesModal
        open={categoryModal.open}
        mode={categoryModal.mode}
        selectedCategories={categoryModal.mode === 'categories' ? form.selectedCategories : form.selectedItems}
        onClose={() => setCategoryModal({ open: false, mode: 'categories' })}
        onDone={(selected) => {
          if (categoryModal.mode === 'categories') {
            update('selectedCategories', selected);
          } else {
            update('selectedItems', selected);
          }
        }}
      />
    </div>
  );
}

