            <div className="flex-1 overflow-y-auto px-3 py-2">
              {MOCK_OUTLETS
                .filter(o => o.name.toLowerCase().includes(outletSearch.toLowerCase()) || o.area.toLowerCase().includes(outletSearch.toLowerCase()))
