let _idCounter = 100;
const uid = (prefix) => `${prefix}${++_idCounter}`;

export const useMenuStore = create((set, get) => ({
  // ΓöÇΓöÇ UI State ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  activeTab: 'builder',
  setActiveTab: (tab) => set({ activeTab: tab }),
  isSimpleMode: false,
  setIsSimpleMode: (mode) => set({ isSimpleMode: mode }),
  showPreviewDrawer: false,
  setShowPreviewDrawer: (show) => set({ showPreviewDrawer: show }),

  hasUnsyncedChanges: false,
  setHasUnsyncedChanges: (val) => set({ hasUnsyncedChanges: val }),

  // ΓöÇΓöÇ Menus ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  menus: initialMenus,
  selectedMenuId: 'm1',
  setSelectedMenuId: (id) => set({ selectedMenuId: id }),
  addMenu: (data) => set((s) => ({ menus: [...s.menus, { id: uid('m'), ...data }] })),
  updateMenu: (id, data) => set((s) => ({ menus: s.menus.map(m => m.id === id ? { ...m, ...data } : m) })),
  deleteMenu: (id) => set((s) => ({ menus: s.menus.filter(m => m.id !== id) })),

  // ΓöÇΓöÇ Builder Selection ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  selectedCategoryId: 'c1',
  setSelectedCategoryId: (id) => set({ selectedCategoryId: id, selectedItemId: null }),
  selectedItemId: null,
  setSelectedItemId: (id) => set({ selectedItemId: id }),

  // legacy
  showItemDrawer: false,
  setShowItemDrawer: (show) => set({ showItemDrawer: show }),
  selectedItemForEdit: null,
  setSelectedItemForEdit: (item) => set({ selectedItemForEdit: item, showItemDrawer: true }),

  categories: initialCategories,
  setCategories: (categories) => set({ categories }),
  addCategory: (data, timing) => set((s) => {
    const id = uid('c');
    return {
      categories: [...s.categories, { id, color: COLORS[s.categories.length % COLORS.length], ...data }],
      categoryTiming: timing ? { ...s.categoryTiming, [id]: timing } : s.categoryTiming
    };
  }),
  updateCategory: (id, data, timing) => set((s) => ({
    categories: s.categories.map(c => c.id === id ? { ...c, ...data } : c),
    categoryTiming: timing ? { ...s.categoryTiming, [id]: timing } : s.categoryTiming
  })),
  deleteCategory: (id) => set((s) => ({
    categories: s.categories.filter(c => c.id !== id),
    items: s.items.filter(i => i.categoryId !== id),
    selectedCategoryId: s.selectedCategoryId === id ? (s.categories.find(c => c.id !== id)?.id || null) : s.selectedCategoryId,
  })),
  moveCategory: (id, direction) => set((s) => {
    const idx = s.categories.findIndex(c => c.id === id);
    if (idx < 0 || (direction === 'up' && idx === 0) || (direction === 'down' && idx === s.categories.length - 1)) return s;
    const newCats = [...s.categories];
    const swapIdx = direction === 'up' ? idx - 1 : idx + 1;
    [newCats[idx], newCats[swapIdx]] = [newCats[swapIdx], newCats[idx]];
    return { categories: newCats };
  }),
  reorderCategory: (sourceId, targetId) => set((s) => {
    const sourceIdx = s.categories.findIndex(c => c.id === sourceId);
    const targetIdx = s.categories.findIndex(c => c.id === targetId);
    if (sourceIdx < 0 || targetIdx < 0 || sourceIdx === targetIdx) return s;
    const newCats = [...s.categories];
    const [moved] = newCats.splice(sourceIdx, 1);
    newCats.splice(targetIdx, 0, moved);
    return { categories: newCats };
  }),

  // ΓöÇΓöÇ Items ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  items: initialItems,
  setItems: (items) => set({ items }),
  addItem: (data) => set((s) => ({ items: [...s.items, { id: uid('i'), inStock: true, stockQty: '', itemCode: '', discount: '0', minOrderQty: '1', maxOrderQty: '', tags: [], description: '', prepTime: '', calories: '', packagingCharge: '0', allergens: [], channels: ['Swiggy', 'Zomato', 'POS', 'Mobile App'], ...data }] })),
  updateItem: (id, data) => set((s) => ({ items: s.items.map(i => i.id === id ? { ...i, ...data } : i) })),
  deleteItem: (id) => set((s) => ({
    items: s.items.filter(i => i.id !== id),
    selectedItemId: s.selectedItemId === id ? null : s.selectedItemId,
  })),
  moveItem: (id, direction) => set((s) => {
    const idx = s.items.findIndex(i => i.id === id);
    if (idx < 0) return s;
    const item = s.items[idx];
    const categoryItems = s.items.filter(i => i.categoryId === item.categoryId);
    const catIdx = categoryItems.findIndex(i => i.id === id);
    if ((direction === 'up' && catIdx === 0) || (direction === 'down' && catIdx === categoryItems.length - 1)) return s;

    const swapItem = direction === 'up' ? categoryItems[catIdx - 1] : categoryItems[catIdx + 1];
    const globalSwapIdx = s.items.findIndex(i => i.id === swapItem.id);

    const newItems = [...s.items];
    [newItems[idx], newItems[globalSwapIdx]] = [newItems[globalSwapIdx], newItems[idx]];
    return { items: newItems };
  }),
  reorderItem: (sourceId, targetId) => set((s) => {
    const sourceIdx = s.items.findIndex(i => i.id === sourceId);
    const targetIdx = s.items.findIndex(i => i.id === targetId);
    if (sourceIdx < 0 || targetIdx < 0 || sourceIdx === targetIdx) return s;
    const newItems = [...s.items];
    const [moved] = newItems.splice(sourceIdx, 1);
    newItems.splice(targetIdx, 0, moved);
    return { items: newItems };
  }),
  duplicateItem: (id) => set((s) => {
    const src = s.items.find(i => i.id === id);
    if (!src) return s;
    return { items: [...s.items, { ...src, id: uid('i'), name: `${src.name} (Copy)` }] };
  }),
  toggleItemStock: (id) => set((s) => ({
    items: s.items.map(i => i.id === id ? { ...i, inStock: !i.inStock, status: i.inStock ? 'Out of Stock' : 'Active', snoozeUntil: null } : i),
  })),
  snoozeItem: (id, snoozeUntil) => set((s) => ({
    items: s.items.map(i => i.id === id ? { ...i, inStock: false, status: 'Out of Stock', snoozeUntil } : i),
  })),
  bulkToggleCategory: (catId, active) => set((s) => ({
    items: s.items.map(i => i.categoryId === catId ? { ...i, status: active ? 'Active' : 'Inactive', inStock: active } : i),
  })),

  // ΓöÇΓöÇ Variants (Per-Item) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  variants: initialVariants,
  addVariant: (data) => set((s) => ({ variants: [...s.variants, { id: uid('v'), ...data }] })),
  updateVariant: (id, data) => set((s) => ({ variants: s.variants.map(v => v.id === id ? { ...v, ...data } : v) })),
  deleteVariant: (id) => set((s) => ({ variants: s.variants.filter(v => v.id !== id) })),

  // ΓöÇΓöÇ Variant Groups (Global) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  variantGroups: initialVariantGroups,
  addVariantGroup: (data) => set((s) => ({ variantGroups: [...s.variantGroups, { id: uid('vg'), ...data }] })),
  updateVariantGroup: (id, data) => set((s) => ({ variantGroups: s.variantGroups.map(g => g.id === id ? { ...g, ...data } : g) })),
  deleteVariantGroup: (id) => set((s) => ({ 
    variantGroups: s.variantGroups.filter(g => g.id !== id),
    globalVariants: s.globalVariants.filter(gv => gv.groupId !== id)
  })),

  // ΓöÇΓöÇ Global Variants (Items under Groups) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  globalVariants: initialGlobalVariants,
  addGlobalVariant: (data) => set((s) => ({ globalVariants: [...s.globalVariants, { id: uid('gv'), ...data }] })),
  updateGlobalVariant: (id, data) => set((s) => ({ globalVariants: s.globalVariants.map(gv => gv.id === id ? { ...gv, ...data } : gv) })),
  deleteGlobalVariant: (id) => set((s) => ({ globalVariants: s.globalVariants.filter(gv => gv.id !== id) })),

  // ΓöÇΓöÇ Addon Groups ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  addonGroups: initialAddonGroups,
  addAddonGroup: (data) => set((s) => ({ addonGroups: [...s.addonGroups, { id: uid('ag'), ...data }] })),
  updateAddonGroup: (id, data) => set((s) => ({ addonGroups: s.addonGroups.map(g => g.id === id ? { ...g, ...data } : g) })),
  deleteAddonGroup: (id) => set((s) => ({
    addonGroups: s.addonGroups.filter(g => g.id !== id),
    addonItems: s.addonItems.filter(ai => ai.groupId !== id),
  })),

  // ΓöÇΓöÇ Addon Items ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  addonItems: initialAddonItems,
  addAddonItem: (data) => set((s) => ({ addonItems: [...s.addonItems, { id: uid('ai'), inStock: true, ...data }] })),
  updateAddonItem: (id, data) => set((s) => ({ addonItems: s.addonItems.map(ai => ai.id === id ? { ...ai, ...data } : ai) })),
  deleteAddonItem: (id) => set((s) => ({ addonItems: s.addonItems.filter(ai => ai.id !== id) })),
  toggleAddonStock: (id) => set((s) => ({
    addonItems: s.addonItems.map(ai => ai.id === id ? { ...ai, inStock: !ai.inStock } : ai)
  })),
  bulkToggleAddonGroup: (groupId, active) => set((s) => ({
    addonItems: s.addonItems.map(ai => ai.groupId === groupId ? { ...ai, inStock: active } : ai)
  })),

  // ΓöÇΓöÇ Item Addon Links ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  itemAddonLinks: initialItemAddonLinks,
  setItemAddonLinks: (itemId, data) => set((s) => ({ itemAddonLinks: { ...s.itemAddonLinks, [itemId]: data } })),

  // ΓöÇΓöÇ Item Variant Links ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  itemVariantLinks: initialItemVariantLinks,
  setItemVariantLinks: (itemId, data) => set((s) => ({ itemVariantLinks: { ...s.itemVariantLinks, [itemId]: data } })),

  // ΓöÇΓöÇ Bulk Linking (Addons & Variants) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  bulkLinkModifier: (groupId, modType, mode, selectionIds) => set((s) => {
    const linkField = modType === 'addon' ? 'itemAddonLinks' : 'itemVariantLinks';
    const currentLinks = { ...s[linkField] };

    // Determine target items
    let targetItems = [];
    if (mode === 'all') {
      targetItems = s.items;
    } else if (mode === 'category') {
      targetItems = s.items.filter(i => selectionIds.includes(i.categoryId));
    } else if (mode === 'item') {
      targetItems = s.items.filter(i => selectionIds.includes(i.id));
    }

    // Apply link to target items
    targetItems.forEach(item => {
      const existing = currentLinks[item.id] || { linked: [], applyToCategory: false };
      if (!existing.linked.includes(groupId)) {
        currentLinks[item.id] = { ...existing, linked: [...existing.linked, groupId] };
      }
    });

    return { [linkField]: currentLinks };
  }),

  // ΓöÇΓöÇ Item & Category Timing ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  itemTiming: initialItemTiming,
  setItemTiming: (itemId, data) => set((s) => ({ itemTiming: { ...s.itemTiming, [itemId]: data } })),

  categoryTiming: {},
  setCategoryTiming: (catId, data) => set((s) => ({ categoryTiming: { ...s.categoryTiming, [catId]: data } })),

  // ΓöÇΓöÇ Taxes ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  taxes: initialTaxes,
  addTax: (data) => set((s) => ({ taxes: [...s.taxes, { id: uid('t'), ...data }] })),
  updateTax: (id, data) => set((s) => ({ taxes: s.taxes.map(t => t.id === id ? { ...t, ...data } : t) })),
  deleteTax: (id) => set((s) => ({ taxes: s.taxes.filter(t => t.id !== id) })),

  // ΓöÇΓöÇ Offers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  offers: initialOffers,
  addOffer: (data) => set((s) => ({ offers: [...s.offers, { id: uid('o'), active: true, itemIds: [], ...data }] })),
  updateOffer: (id, data) => set((s) => ({ offers: s.offers.map(o => o.id === id ? { ...o, ...data } : o) })),
  deleteOffer: (id) => set((s) => ({ offers: s.offers.filter(o => o.id !== id) })),
  toggleOffer: (id) => set((s) => ({ offers: s.offers.map(o => o.id === id ? { ...o, active: !o.active } : o) })),

  // ΓöÇΓöÇ Modifiers / Links (legacy) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  activeModifierTab: 'addons',
  setActiveModifierTab: (tab) => set({ activeModifierTab: tab }),
  links: { s1: ['c1','c2','c3'], s2: ['c1','c2','c3','c4'], s3: ['c1','c2'], s4: ['c4'] },
  setLinks: (updater) => set((state) => ({
    links: typeof updater === 'function' ? updater(state.links) : updater,
  })),

  // ΓöÇΓöÇ Menu Pushing ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  pushHistory: [
    { id: 'ph1', date: new Date(Date.now() - 86400000).toISOString(), platforms: ['Swiggy', 'Zomato'], status: 'Success', notes: 'Weekend Price Update' }
  ],
  scheduledPushes: [],
  schedulePush: (data) => set((s) => ({ 
    scheduledPushes: [...s.scheduledPushes, { id: uid('sp'), ...data }] 
  })),
  cancelPush: (id) => set((s) => ({
    scheduledPushes: s.scheduledPushes.filter(p => p.id !== id)
  })),
  recordPush: (data) => set((s) => ({
    pushHistory: [{ id: uid('ph'), date: new Date().toISOString(), status: 'Success', ...data }, ...s.pushHistory]
  })),
}));
